import{_ as o,o as d,c,a2 as t}from"./chunks/framework.D6RJXrbK.js";const m=JSON.parse('{"title":"附录 D 练习参考答案","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/d-answers.md","filePath":"appendix/d-answers.md","lastUpdated":1791513046000}'),r={name:"appendix/d-answers.md"};function a(i,e,l,n,s,u){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="附录-d-练习参考答案" tabindex="-1">附录 D 练习参考答案 <a class="header-anchor" href="#附录-d-练习参考答案" aria-label="Permalink to &quot;附录 D 练习参考答案&quot;">​</a></h1><p>说明：</p><ul><li><strong>巩固题</strong>给出答案。能运行的都实际运行过（用 mini-openfga v1.0 或本书使用的 OpenFGA v1.22 服务），标注为“（已验证）”；</li><li><strong>读源码题</strong>给出出处，引用的行号都在 <code>526995eb</code> 上核对过；</li><li><strong>扩展题</strong>给出思路和要点，除非特别注明，<strong>没有</strong>给出可运行的实现，也没有实测。</li></ul><hr><h2 id="第-0-章" tabindex="-1">第 0 章 <a class="header-anchor" href="#第-0-章" aria-label="Permalink to &quot;第 0 章&quot;">​</a></h2><ol><li>运行器输出 <code>Check assertions: 325 passed, 191 failed, 0 skipped (63.0%); tests: 78/157 fully passed</code>（已验证，v0.1 上实际运行的输出）。注意第 8 章的踩坑记录：这个数字是在一个有 bug 的运行器上得到的。</li><li>不含 <code>web/dist</code> 和 <code>package-lock.json</code> 的统计（已验证）：v0.1→v0.2 +1329/−192，v0.2→v0.3 +1760/−38，v0.3→v0.4 +1300/−76，<strong>v0.4→v0.5 +3359/−167（最大，存储接口、SQLite、HTTP API 一起加入）</strong>，v0.5→v0.6 +1313/−3，v0.6→v1.0 +2823/−68。</li><li><code>assets/assets.go:24</code> 用 <code>//go:embed tests/*</code> 把测试目录嵌进二进制；使用它们的是 <code>tests/check/check.go</code>、<code>tests/listobjects/listobjects.go</code>、<code>tests/listusers/listusers.go</code>（<code>AGENTS.md</code> 的 Testing 部分）。</li></ol><h2 id="第-1-章" tabindex="-1">第 1 章 <a class="header-anchor" href="#第-1-章" aria-label="Permalink to &quot;第 1 章&quot;">​</a></h2><ol><li><code>team:platform#member@team:infra#member</code>；模型 <code>define member: [user, team#member]</code>，类型限制里必须有 <code>team#member</code>，嵌套才能写入并生效（Lab 4 的公司模型就是这样，已验证）。</li><li>加一个类型 <code>system</code>，<code>define admin: [user]</code>；<code>document</code> 加 <code>define system: [system]</code>、<code>define viewer: [user] or admin from system</code>，每份文档写一条 <code>document:x#system@system:global</code>（已验证：<code>system:global#admin@user:root</code> 让 root 能看两份文档，bob 不能）。不能写 <code>document:*</code>：通配符只能出现在 user 一侧，表示“该类型的所有主体”，不能表示“所有对象”。</li><li><code>Tupleset</code>（对应 <code>from parent</code> 的 <code>parent</code>）和 <code>ComputedUserset</code>（对应 <code>viewer</code>），<code>authzmodel.pb.go:1046–1047</code>。</li></ol><h2 id="第-2-章" tabindex="-1">第 2 章 <a class="header-anchor" href="#第-2-章" aria-label="Permalink to &quot;第 2 章&quot;">​</a></h2><ol><li><code>cmd/run/run.go:799</code> 用 <code>rs/cors</code> 包装 HTTP 处理器；默认 <code>CORSAllowedOrigins</code> 是 <code>[&quot;*&quot;]</code>（<code>pkg/server/config/config.go:902</code>），即允许任何来源。</li><li>日志拦截器的注释写着 “needed to log invalid requests”（<code>run.go</code> 中 <code>logging.NewLoggingInterceptor</code> 那一行）。校验拦截器放到它前面，校验失败的请求在到达日志拦截器之前就返回了，这些请求不会被记录。</li><li><code>CheckCommand.maxConcurrentReads</code>（<code>pkg/server/commands/check_command.go:37</code>）被放进 <code>storagewrappers.Operation.Concurrency</code>（:134），在 <code>NewRequestStorageWrapper</code> 里交给 <code>NewBoundedTupleReader</code>（<code>pkg/storage/storagewrappers/request.go:47</code>），它用一个容量为该值的信号量限制同时进行的存储读取。</li></ol><h2 id="第-3-章" tabindex="-1">第 3 章 <a class="header-anchor" href="#第-3-章" aria-label="Permalink to &quot;第 3 章&quot;">​</a></h2><ol><li>dave 经 design → eng-docs → eng → root 的 <code>viewer from parent</code> 链得到 viewer；<code>blocked</code> 直接包含 dave，<code>but not</code> 的结果为 false（已验证：<code>viewer@dave</code> true，<code>blocked@dave</code> true，<code>can_view@dave</code> false）。两侧并发执行，blocked 先返回时 base 一侧被取消，读取次数会变少，所以<strong>会</strong>影响 <code>datastore_query_count</code>（Lab 5 观察到同一个 Check 读取次数不同）。</li><li>OpenFGA 返回 <code>{&quot;allowed&quot;:true}</code>（已验证，对 <code>can_view</code> 和 <code>viewer</code> 都是）。路径是 design → <code>viewer from parent</code> → eng-docs → eng，到达 <code>folder:eng#viewer@folder:eng#viewer</code>，<code>ResolveCheck</code> 里的 <code>tuple.IsSelfDefining</code>（<code>internal/graph/check.go:434</code>）认为一个 userset 总是它自己的成员。</li><li>深度只在 <code>dispatch</code> 里加一（<code>check.go:383</code>，recursive 策略里另有一处 <code>recursive_resolver.go:278</code>），每次加 1，从 0 开始，不会跳过 25，所以 <code>==</code> 足够；<code>&gt;=</code> 只是更稳妥。</li></ol><h2 id="第-4-章" tabindex="-1">第 4 章 <a class="header-anchor" href="#第-4-章" aria-label="Permalink to &quot;第 4 章&quot;">​</a></h2><ol><li>根是 <code>Difference</code>：base 是 <code>Union(This[user], Computed a)</code>，subtract 是 <code>Intersection(Computed b, Computed c)</code>。</li><li>已验证的差异：<code>define a: [user]&lt;制表符&gt;# 注释</code>，<strong>mini 接受，OpenFGA 的解析器拒绝</strong>（<code>no viable alternative at input &#39;\\t&#39;</code>）。两者对 <code> # 注释</code>（空格）都接受，对 <code>[user]# 注释</code>（无空白）都拒绝。</li><li><code>ExitRelationDeclaration</code>（<code>transformer/dsltojson.go:270</code>）在把关系放进当前类型之前检查 <code>l.currentTypeDef.GetRelations()[relationName] != nil</code>，存在就报 <code>&#39;%s&#39; is already defined in &#39;%s&#39;</code>。mini 在解析器里检查：<code>pkg/dsl/parser.go:151</code>，<code>duplicate relation &#39;%s&#39; in type &#39;%s&#39;</code>。</li></ol><h2 id="第-5-章" tabindex="-1">第 5 章 <a class="header-anchor" href="#第-5-章" aria-label="Permalink to &quot;第 5 章&quot;">​</a></h2><ol><li><strong>不能通过</strong>。<code>a</code> 的唯一入口在 <code>[user] and b</code>，<code>b</code> 又只是 <code>a</code>：交集要求 b 也有入口，而 b 的入口只能来自 a，形成“潜在循环”。两边都拒绝，信息相同（已验证）：<code>the definition of relation &#39;a&#39; in object type &#39;doc&#39; is invalid: potential loop</code>。</li><li>放在服务层 <code>pkg/server/models.go</code>（<code>MaxTypesPerModel = 100</code>，超过时报 <code>exceeded_entity_limit</code>）。这是一个<strong>写入时的资源限制</strong>，不是模型的语义规则：OpenFGA 同样放在 <code>WriteAuthorizationModelCommand</code> 里；TypeSystem 还会被用来加载已存储的模型，在那里做限制会让历史模型无法读取。</li><li><code>typesystem.go:1455</code>：类型限制里的 <code>RelationReference</code> 设置了 <code>oneof</code> 但内容为空（<code>Relation{Relation: &quot;&quot;}</code> 或 <code>Wildcard{}</code> 为 nil），源码注释就是这样描述的。DSL 的语法里 <code>#</code> 后面必须有关系名、<code>:*</code> 是固定写法，写不出空引用；JSON（protobuf）可以构造任意结构。</li></ol><h2 id="第-6-章" tabindex="-1">第 6 章 <a class="header-anchor" href="#第-6-章" aria-label="Permalink to &quot;第 6 章&quot;">​</a></h2><ol><li>已验证（mini 和 OpenFGA 结果、信息完全相同）：<code>user:*</code> 拒绝（类型限制里没有 <code>user:*</code>）；<code>group:a#owner</code> 拒绝（<code>group#owner</code> 不在限制里）；<code>group:a</code> 拒绝（<code>group</code> 不是允许的直接类型）；<code>group:a#member</code> 接受。</li><li>tupleset 的含义是“对象的父对象是谁”，父必须是一个具体对象。如果允许 <code>document:1#parent@folder:x#viewer</code>，<code>viewer from parent</code> 就要先把“folder:x 的所有 viewer”展开成对象集合，再对其中每个对象求 viewer，语义上变成了“父是一组用户”，既无法和 <code>from</code> 的含义对应，又会让求值成本不可控。</li><li><code>HasTypeInfo</code>（<code>typesystem.go:827</code>）在 schema 版本不受支持（1.0）或关系没有类型信息（<code>GetTypeInfo() == nil</code>）时返回 false；schema 1.0 的模型没有类型限制。</li></ol><h2 id="第-7-章" tabindex="-1">第 7 章 <a class="header-anchor" href="#第-7-章" aria-label="Permalink to &quot;第 7 章&quot;">​</a></h2><ol><li><code>[user]</code>：<code>ReadUserTuple(store, &quot;document:1&quot;, &quot;viewer&quot;, &quot;user:anne&quot;)</code>，以及通配符 <code>ReadUserTuple(..., &quot;user:*&quot;)</code>（如果允许）；<code>[group#member]</code>：<code>ReadUsersetTuples(ReadUsersetTuplesFilter{Object: &quot;document:1&quot;, Relation: &quot;viewer&quot;, AllowedTypes: [group#member]})</code>；<code>viewer from parent</code>：<code>Read(ReadFilter{Object: &quot;document:1&quot;, Relation: &quot;parent&quot;})</code>。之后对每个组、每个父对象派发子问题，各自产生新的读取。</li><li>调用方（比如条件求值时的 <code>Normalize</code>）可能修改返回的元组，与其他并发请求读同一份数据形成数据竞争。测试：两个 goroutine 读同一条元组，一个修改它的 condition context，<code>go test -race</code> 会报告（第 14 章遇到的就是这一类问题）。（思路，未实现。）</li><li>weight2 和 recursive 策略要对两个有序流做“归并求交”，需要先看一眼当前元素而不消费它：<code>internal/graph/weight_two_resolver.go:334</code>、<code>:412</code> 的 <code>stream.Head(ctx)</code>。</li></ol><h2 id="第-8-章" tabindex="-1">第 8 章 <a class="header-anchor" href="#第-8-章" aria-label="Permalink to &quot;第 8 章&quot;">​</a></h2><ol><li><code>can_share = owner and can_view</code>；alice 是 eng 文件夹的 editor，不是 design 的 owner，<code>owner</code> 为 false，交集为 false（v0.1 和 v1.0 都已验证）。</li><li>失败的会是“union 中一条路有条件错误、另一条路为 true”的用例，比如第 20 章提到的 <code>relation_through_ttu_with_condition</code>（一个父文件夹的条件缺参数，另一个满足）。期望 true，改坏后得到错误。（思路，未实测。）</li><li>由公式 <code>eval(b) ∧ ¬eval(s)</code>：把“s 不确定”当作 s 为真，结果是 false，即<strong>拒绝</strong>；当作假则可能错误地放行。授权系统里错误的拒绝比错误的放行更安全，所以这是更安全的选择。（第 12 章 12.3.1 节补充了一个例外：只通过自身递归的关系里，环不是“不确定”。）</li></ol><h2 id="第-9-章" tabindex="-1">第 9 章 <a class="header-anchor" href="#第-9-章" aria-label="Permalink to &quot;第 9 章&quot;">​</a></h2><ol><li>根 <code>document:design#viewer@user:ceo</code>（Depth 0，Visited={根}）→ union：直接赋值（不派发）、<code>editor</code>（同对象，计算关系，不加深度）、<code>viewer from parent</code> → 派发 <code>folder:eng-docs#viewer@user:ceo</code>（Depth 1，Visited 加入它）→ … → <code>folder:eng#viewer</code>（Depth 2）→ <code>folder:root#viewer</code>（Depth 3，直接元组 <code>folder:root#viewer@user:ceo</code> 为 true）。<code>editor</code> 一侧也沿 <code>editor from parent</code> 逐层派发，每个分支有自己的 Visited 副本。</li><li>被取消前没有执行的闭包不会计数，所以 mini 的计数只包含真正开始的派发，比在构造闭包时计数更接近“实际做了多少工作”。OpenFGA 在 <code>dispatch</code> 闭包里加深度、在 <code>ResolveCheck</code> 里统计派发，同样是在执行时计数。</li><li>解析链是一个环形链表，LocalChecker 可能被缓存、限流、影子解析器包在里面，调用方拿到的是链头。<code>LocalCheckResolver</code>（<code>internal/graph/builder.go:116</code>）沿 <code>GetDelegate()</code> 找，遇到 <code>ShadowResolver</code> 取它的 <code>main</code>，并防止“委托就是自己”造成的无限循环。</li></ol><h2 id="第-10-章" tabindex="-1">第 10 章 <a class="header-anchor" href="#第-10-章" aria-label="Permalink to &quot;第 10 章&quot;">​</a></h2><ol><li>容量为 0 时，生产者在发送结果时阻塞，直到有人接收。如果 union 已经因为某个 true 短路返回，其余的生产者就永远阻塞，goroutine 泄漏。场景：<code>a or b</code>，a 很快为 true、b 较慢；union 返回后 b 的 goroutine 卡在发送上。</li><li>subtract 便宜、base 昂贵、而且 subtract 经常为 true 时，先算 subtract 更快；subtract 很少为 true 时，串行化让延迟变成两者之和，比并发更慢。并发执行的好处是延迟取两者中“决定结果”的那一个。（思路。）</li><li>测试把一个生产者人为阻塞 300ms（<code>blockedProducerDelay</code>），用 <code>runtime/metrics</code> 读取进程的用户态 CPU 时间（<code>/cpu/classes/user:cpu-seconds</code>），要求这段时间里消耗的 CPU 少于 100ms（<code>spinCPUBudget</code>）。如果在已关闭的通道上反复 select，就会在等待期间空转烧 CPU。</li></ol><h2 id="第-11-章" tabindex="-1">第 11 章 <a class="header-anchor" href="#第-11-章" aria-label="Permalink to &quot;第 11 章&quot;">​</a></h2><ol><li>已验证都为 true。<code>user:bob</code>：命中 <code>doc:1#viewer@user:*</code>（通配符分支，<code>checkPublicAssignable</code>）；<code>group:a#member</code>：作为 userset 用户，命中元组 <code>doc:1#viewer@group:a#member</code>（直接匹配）。</li><li>思路：对象上有大量 userset 元组时，<code>ReadUsersetTuples</code> 返回很多行，而 <code>ReadUserTuple(user:*)</code> 是一次主键查找。OpenFGA 选择前者是因为它要同时处理带条件的通配符元组和多个通配符类型；基准测试应该能看到两者随 userset 元组数量的差距。（未实测。）</li><li><code>default_resolver.go:269</code>：<code>dispatchParams</code> 非空但 <code>parentReq</code> 或 <code>tk</code> 为空，只可能是程序错误（构造消息时漏了字段）。返回 <code>ErrPanic</code> 表示“不该发生的内部错误”，比静默跳过安全。</li></ol><h2 id="第-12-章" tabindex="-1">第 12 章 <a class="header-anchor" href="#第-12-章" aria-label="Permalink to &quot;第 12 章&quot;">​</a></h2><ol><li>已验证为 true。子问题树：<code>a#member@x</code> → userset 元组 <code>a#member@b#member</code> → 派发 <code>b#member@x</code> → 直接元组 <code>b#member@user:x</code> 为 true（同时 <code>b#member@a#member</code> → 派发 <code>a#member@x</code>，在路径上已出现，检测到环）。union 中有 true，环不影响结果。</li><li>例子：<code>doc#viewer: [group#member]</code>，<code>doc:1#viewer@group:a#member</code>、<code>doc:1#viewer@group:b#member</code>，<code>group:a#member@group:c#member</code>、<code>group:b#member@group:c#member</code>、<code>group:c#member@user:x</code>。两个并发分支都会经过 <code>c#member@x</code>；如果 Visited 共享，后到的分支会把它当成环，如果先到的分支恰好被取消，答案就可能变成错误的 false。</li><li><code>cycle_and_cycle_return_false</code>（<code>consolidated_1_1_tests.yaml:8163</code> 起）：<code>viewer: [user, document#editor] and editor</code>，<code>editor: [user, document#viewer]</code>，两条元组让 viewer 和 editor 互相引用。intersection 的规则：任一操作数为 false 或环，结果为 false。期望 false。</li></ol><h2 id="第-13-章" tabindex="-1">第 13 章 <a class="header-anchor" href="#第-13-章" aria-label="Permalink to &quot;第 13 章&quot;">​</a></h2><ol><li>模型：<code>type incident</code>；<code>type logs</code>，<code>define reader: [user] or oncall from incident</code>、<code>define incident: [incident]</code>；<code>incident</code> 上 <code>define oncall: [user]</code>。请求：Check <code>logs:prod#reader@user:anne</code>，上下文元组 <code>incident:current#oncall@user:anne</code>（当前值班表由调用方的排班系统提供，不写入 OpenFGA）。</li><li>缓存键必须包含上下文元组和请求的 <code>context</code>。<code>pkg/storage/cache.go:332</code> 的 <code>InvariantCacheKey(storeID, modelID, ctx, contextualTuples...)</code> 正是这样：先复制并排序上下文元组，再和 context 一起哈希。mini 的 <code>CacheKey</code> 用 <code>invariantKey</code> 做同样的事。</li><li><code>ReadStartingWithUser</code> 可以要求按对象 ID 升序返回（<code>WithResultsSortedAscending</code>），<code>CombinedTupleReader</code> 此时用 <code>NewOrderedCombinedIterator</code> 把上下文元组和存储结果归并（<code>combinedtuplereader.go:189</code>），归并要求两边都有序，所以上下文元组预先排好序。</li></ol><h2 id="第-14-章" tabindex="-1">第 14 章 <a class="header-anchor" href="#第-14-章" aria-label="Permalink to &quot;第 14 章&quot;">​</a></h2><ol><li>条件 <code>condition in_allowed_countries(country: string, allowed: list&lt;string&gt;) { country in allowed }</code>；类型限制 <code>define viewer: [user with in_allowed_countries]</code>；元组 <code>doc:1#viewer@user:anne with in_allowed_countries {&quot;allowed&quot;: [&quot;DE&quot;, &quot;FR&quot;]}</code>；请求 <code>context: {&quot;country&quot;: &quot;DE&quot;}</code>（参数一部分来自元组、一部分来自请求，第 14 章的合并规则）。已验证：<code>country=DE</code> 为 true，<code>country=US</code> 为 false。</li><li>把密级做成对象之间的关系：<code>type clearance</code>，用户 <code>user:x</code> 是 <code>clearance:secret#holder</code>，文档写 <code>document:1#required@clearance:secret</code>；“级别 ≥ 密级”用层级关系表达：<code>clearance:top_secret#implies@clearance:secret</code> 之类，<code>define can_read: holder from required</code>，配合 <code>holder: [user] or holder from implies_from</code>。条件适合处理请求时才知道的值（时间、IP），对象属性本身更适合建模成元组。（思路。）</li><li>注释（<code>internal/condition/eval/eval.go</code> 中 <code>EvaluateInlineExpression</code>）解释得很清楚：请求的 context 是整个请求共享的，可能包含给<strong>其他</strong>元组用的字段；没有声明参数的表达式如果收到这些字段，会报“没有定义参数”之类的错误。</li></ol><h2 id="第-15-章" tabindex="-1">第 15 章 <a class="header-anchor" href="#第-15-章" aria-label="Permalink to &quot;第 15 章&quot;">​</a></h2><ol><li>链的组成依赖按 store 查询的特性开关，例如 <code>getCheckResolverBuilder(storeID)</code>（<code>pkg/server/check.go:455</code>）里的 <code>WithOptimizations(featureFlagClient.Boolean(..., storeID))</code> 和 <code>WithShadowResolverEnabled(...)</code>。不同 store 可能有不同的链，所以每个请求构建一次。另外，派发限流器也是在这里按请求创建的（第 15 章的更正）。</li><li>键：store ID、模型 ID（或模型无关时省略）、读法和参数（object、relation、允许的类型、用户）、上下文元组和条件 context 的不变键。失效：缓存条目记录写入时间，读取时与 <code>LastCacheInvalidationTime</code> 比较，早于它的作废；OpenFGA 的缓存控制器对迭代器缓存还按 <code>object#relation</code>、<code>user + 对象类型</code> 做部分失效（第 23 章）。（思路。）</li><li><code>ResolveCheckResponse</code> 包含 <code>ResolutionMetadata</code>，调用方会修改它（例如 union 把 <code>CycleDetected</code> 置为 true，<code>check.go:203</code>、<code>:277</code>）。不克隆的话，缓存里的对象会被并发的请求修改，既有数据竞争，又会让后来的命中读到被改过的元数据。</li></ol><h2 id="第-16-章" tabindex="-1">第 16 章 <a class="header-anchor" href="#第-16-章" aria-label="Permalink to &quot;第 16 章&quot;">​</a></h2><ol><li>已验证（OpenFGA）：根节点是 <code>difference</code>，base 是叶子 <code>{&quot;computed&quot;: {&quot;userset&quot;: &quot;document:design#viewer&quot;}}</code>，subtract 是叶子 <code>{&quot;computed&quot;: {&quot;userset&quot;: &quot;document:design#blocked&quot;}}</code>。</li><li>思路：BFS，队列里放 <code>object#relation</code>，已展开集合去重；对叶子里的 <code>users</code> 中形如 <code>x#y</code> 的元素和 <code>computed</code>、<code>tupleToUserset</code> 节点继续调用 Expand；最后得到的具体用户集合应与 ListUsers 一致，但 <code>and</code>/<code>but not</code> 需要客户端自己做集合运算，这正是 ListUsers 存在的原因。（未实现。）</li><li>对 <code>group:eng#member</code> 本身调用 Expand（object <code>group:eng</code>，relation <code>member</code>）。</li></ol><h2 id="第-17-章" tabindex="-1">第 17 章 <a class="header-anchor" href="#第-17-章" aria-label="Permalink to &quot;第 17 章&quot;">​</a></h2><ol><li>不会全部合并：两项键相同且 context 相同的会合并成一次求值，带不同 context 的那一项单独求值。OpenFGA 的去重键包含 context 和上下文元组（<code>batch_check_command.go:232</code> 的 <code>generateCacheKeyFromCheck</code> 调用 <code>InvariantCacheKey(storeID, authModelID, check.GetContext(), check.GetContextualTuples()...)</code>）；mini 的 <code>BatchCheck</code> 也用包含它们的 <code>CacheKey</code>（已核对代码）。</li><li>只读的话可以共享，节省重复构造；风险在于共享对象内部的可变状态（例如迭代器缓存、读取计数）会在各项之间串扰，单项的 <code>datastore_query_count</code> 会变得不准确。（思路。）</li><li><code>pkg/server/batch_check.go</code> 中，<code>errors.As(err, &amp;BatchCheckValidationError)</code> 为真时转成 <code>serverErrors.ValidationError</code>（整个请求 400）；单项求值的错误不会让整个请求失败，而是写进该项结果的 <code>error</code> 字段。</li></ol><h2 id="第-18-章" tabindex="-1">第 18 章 <a class="header-anchor" href="#第-18-章" aria-label="Permalink to &quot;第 18 章&quot;">​</a></h2><ol><li>从 <code>user:alice</code> 出发：读 <code>ReadStartingWithUser(object_type=folder, relation=editor, users=[user:alice])</code> 得到 <code>folder:eng</code>；沿 <code>editor from parent</code> 反向：<code>ReadStartingWithUser(object_type=folder, relation=parent, users=[folder:eng])</code> 得到 <code>folder:eng-docs</code>，<code>ReadStartingWithUser(object_type=document, relation=parent, users=[folder:eng])</code>（无）；再从 <code>folder:eng-docs</code>：<code>ReadStartingWithUser(object_type=document, relation=parent, users=[folder:eng-docs])</code> 得到 <code>document:design</code>。结果 <code>[document:design]</code>（结果已用 CLI 验证；读取参数是推导；文档上 <code>editor: [user]</code> 也会查 <code>ReadStartingWithUser(document, editor, [user:alice])</code>，无结果。）</li><li>思路：把“读完再遍历”改成边读边处理，用计数器在达到 <code>MaxResults</code> 时取消上下文、关闭迭代器。大文件夹下，首个结果的延迟和内存占用都会明显下降。（未实测。）</li><li><code>GetPrunedRelationshipEdges</code> 对交集只取第一个操作数、对排除只取 base，并标记 <code>RequiresFurtherEval</code>；<code>GetRelationshipEdges</code> 返回全部边。非测试代码只用到剪枝版本（<code>list_users_rpc.go:331</code>、<code>reverse_expand.go:432</code>），非剪枝版本只在测试里用到。</li></ol><h2 id="第-19-章" tabindex="-1">第 19 章 <a class="header-anchor" href="#第-19-章" aria-label="Permalink to &quot;第 19 章&quot;">​</a></h2><ol><li>剪枝时交集取<strong>第一个</strong>操作数（<code>internal/graph/graph.go:298</code>，<code>t.Intersection.GetChild()[0]</code>）。<code>editor and can_view</code> 沿 <code>editor</code> 找候选；写成 <code>can_view and editor</code> 就沿 <code>can_view</code> 找，候选集变成所有能看的对象，通常大得多，而且 <code>can_view</code> 本身含 <code>but not</code>，每个候选都要复核。把<strong>更有选择性、更简单</strong>的操作数放在前面更好。</li><li>思路：<code>Y</code> 为直接关系时，一次 <code>ReadStartingWithUser(type, Y, [user, user:*])</code> 得到被排除的对象集合，从候选里减掉即可，不再逐个 Check。流水线的 <code>DifferenceDirectSubtract</code> 也是在 subtract 一侧能直接查到（通配符直连）时，用集合操作代替逐个求值。（未实现。）</li><li><code>createWorker</code>（<code>pipeline.go:155</code>）按节点类型选择：具体类型、通配符、类型#关系节点用基础 worker；运算节点按标签选 <code>Intersection</code>、<code>Difference</code>（满足条件且开启 <code>FlagOptimizeSubtract</code> 时用 <code>DifferenceDirectSubtract</code>）、<code>Union</code>。顺便一提：判断写成 <code>b.config.Flags&amp;FlagOptimizeSubtract == 1</code>，因为 <code>FlagOptimizeSubtract</code> 恰好是 <code>1 &lt;&lt; 0</code> 才成立；如果将来在它前面加一个标志，这个判断会悄悄失效，写成 <code>!= 0</code> 更稳妥。</li></ol><h2 id="第-20-章" tabindex="-1">第 20 章 <a class="header-anchor" href="#第-20-章" aria-label="Permalink to &quot;第 20 章&quot;">​</a></h2><ol><li>已验证（mini 和 OpenFGA 相同）：<code>{&quot;users&quot;:[{&quot;wildcard&quot;:{&quot;type&quot;:&quot;user&quot;}}]}</code>，bob 不出现；单独 Check bob 为 false。</li><li>10 万个候选、每个一次完整的 Check，成本和延迟都很高。优化：收集候选时记录路径上是否经过 <code>and</code>、<code>but not</code> 或带条件的元组，没有经过的候选直接确认为结果，只对其余的做 Check。（思路，未实现。）</li><li>与第 12 章的规则一致：subtract 一侧有环被当作“不确定”，排除的结果为 false，即“没有人满足”，于是整个排除返回空集。但第 31 章发现这和 OpenFGA 自己的 Check 不一致：只通过自身递归的关系里，Check 不认为那是环。</li></ol><h2 id="第-21-章" tabindex="-1">第 21 章 <a class="header-anchor" href="#第-21-章" aria-label="Permalink to &quot;第 21 章&quot;">​</a></h2><ol><li>缓存控制器根据 changelog 里最新变更的时间判断缓存是否过期。如果元组先提交、changelog 后写，中间这段时间里读到的“最新变更时间”不包含这次写入，新写入的数据可能被旧缓存遮住；更糟的是，如果 changelog 写入失败，这次变更永远不会触发失效。</li><li>要改：占位符（<code>?</code> → <code>$1</code>）、<code>INSERT ... ON CONFLICT</code> 的写法、行值 <code>IN</code> 的写法（Postgres 支持）、类型（<code>BYTEA</code> 等）、连接池配置。<code>storagetest.RunAll</code> 只依赖 <code>OpenFGADatastore</code> 接口，可以原样复用。（思路。）</li><li>排序：<code>makeTupleLockKeys</code> 的注释是 “flattens deletes+writes into a deduped, sorted slice to ensure stable lock order”，所有事务以相同顺序加锁，避免两个事务互相等待对方的锁（死锁）。分批：限制单条 <code>SELECT</code> 里的参数数量，避免超过数据库对单条语句参数个数的限制，也让每条语句的规模可控。</li></ol><h2 id="第-22-章" tabindex="-1">第 22 章 <a class="header-anchor" href="#第-22-章" aria-label="Permalink to &quot;第 22 章&quot;">​</a></h2><ol><li>模型变化后，旧的元组可能不再符合新模型（例如删掉了 <code>[group#member]</code> 这个限制）。如果删除也按当前模型校验，这些已经存在、已经无效的元组就再也删不掉了。场景：先写 <code>doc:1#viewer@group:a#member</code>，再写一个 <code>viewer: [user]</code> 的新模型，然后删除那条元组。</li><li>要扩展 <code>Write</code> 的选项（OpenFGA 是 <code>storage.WithOnDuplicateInsert</code>、<code>WithOnMissingDelete</code>）。内存后端：已存在时跳过、不存在时跳过；SQLite：<code>INSERT ... ON CONFLICT DO NOTHING</code>、删除不检查 <code>RowsAffected</code>。注意 changelog 只应记录实际发生的变更。（思路。）</li><li>两者都是用 base64 编码器（<code>encoder.NewBase64Encoder()</code>）包装后端返回的令牌；SQLite 后端返回的都是“下一页第一行的 ID”（多查一行判断是否有下一页）：模型按 ID 倒序（从新到旧），store 按 ID 正序。</li></ol><h2 id="第-23-章" tabindex="-1">第 23 章 <a class="header-anchor" href="#第-23-章" aria-label="Permalink to &quot;第 23 章&quot;">​</a></h2><ol><li>不会漏：令牌之后的变更都会被读到（前提是 changelog 和元组同事务写入，第 21 章）。会重复：处理完一批、还没保存新令牌就崩溃，重启后会再处理一次。让处理幂等：按“元组 + 操作”的结果写入（写入已存在的忽略、删除不存在的忽略），或者记录已处理的变更 ULID。</li><li>思路：<code>start_time</code> 非空且没有令牌时，用 <code>ulid.New(ulid.Timestamp(t), nil)</code> 生成一个只有时间部分的 ULID 作为起点（OpenFGA 的 <code>ReadChangesQuery.Execute</code> 就是这样）。测试：在两次写入之间记一个时间，带这个时间读，只应读到第二次写入。（未实现。）</li><li><code>invalidateIteratorCacheByObjectRelation</code> 对应正向的读法（<code>Read(object#relation)</code>、<code>ReadUsersetTuples</code>、<code>ReadUserTuple</code>，按对象和关系定位）；<code>invalidateIteratorCacheByUserAndObjectType</code> 对应反向的 <code>ReadStartingWithUser</code>（按用户和对象类型定位）。见 <code>cache_controller.go:370</code>、<code>:376</code>。</li></ol><h2 id="第-24-章" tabindex="-1">第 24 章 <a class="header-anchor" href="#第-24-章" aria-label="Permalink to &quot;第 24 章&quot;">​</a></h2><ol><li>客户端自己对协议的理解可能有误（JSON 字段名、包装层级、错误码），如果只在 mini 上跑，两边可能“一起错”而测试照样通过。在真实 OpenFGA 上通过，证明客户端是对的，再拿它测 mini 才有意义。第 23 章断言里的 <code>contextual_tuples</code> 就是这类问题的例子。</li><li>思路：处理函数设置 <code>Content-Type</code>，ListObjects 通过回调或通道每得到一个确认的对象就写一行 JSON 并 <code>Flush()</code>；第 18 章的实现需要把“收集到切片再返回”改成“产出一个、发送一个”，并在客户端断开时取消上下文。（未实现。）</li><li><code>network, address := tcp, config.GRPC.Addr</code>（<code>run.go</code> 中 <code>config.HTTP.Enabled</code> 分支的开头），回退时 <code>goto DIAL_SERVER</code> 跳过 UDS，直接用这个 TCP 地址；<code>dialLocalGrpc</code>（:681）会把未指定的主机（<code>0.0.0.0</code> 或空）换成 <code>localhost</code>。</li></ol><h2 id="第-25-章" tabindex="-1">第 25 章 <a class="header-anchor" href="#第-25-章" aria-label="Permalink to &quot;第 25 章&quot;">​</a></h2><ol><li>模型以结构化的 JSON（protobuf）存储，DSL 是从结构重新生成的，注释、空行、缩进都不在结构里。要保留，得把 DSL 原文和模型一起存；OpenFGA 的 <code>WriteAuthorizationModel</code> 只接受结构化模型，做不到（这也是 FGA CLI 和 VS Code 插件把 <code>.fga</code> 文件放在代码仓库里管理的原因）。</li><li>思路：错误类型里带上类型名和关系名（mini 的校验错误信息里已经有，例如 <code>undefined relation: &#39;document#banned&#39;</code>），前端在 DSL 文本里定位 <code>type &lt;类型&gt;</code> 之后第一个 <code>define &lt;关系&gt;</code> 的行号。（未实现。）</li><li>默认 <code>false</code>（<code>config.go:931</code>，已验证）。<code>net.Dial</code> 有两个作用：确认 HTTP 服务已经起来（带指数退避，最多 3 秒）；用 <code>conn.RemoteAddr().String()</code> 得到实际的地址填进模板里的 <code>fga_api_host</code>。</li></ol><h2 id="第-26-章" tabindex="-1">第 26 章 <a class="header-anchor" href="#第-26-章" aria-label="Permalink to &quot;第 26 章&quot;">​</a></h2><ol><li>已验证：根节点变为 false，<code>viewer@dave</code> 也变为 false。base 已经是 false，<code>but not</code> 的结果与 subtract 无关，<code>blocked</code> 子树不再重要（它仍然是 true）。</li><li>思路：用一个 map 记录已求值的 <code>object#relation@user</code> → 结果节点；再次遇到时插入一个引用节点。结果为 <code>cycle</code> 的节点<strong>不能</strong>复用，它取决于到达它的路径；第 31 章的 <code>PathDependent</code> 结果同理。（未实现。）</li><li>追踪多了时间（每个 span 的耗时）、并发关系和存储查询的细节；少了被短路取消的分支（它们只有开始没有结果，或根本没有开始），也就看不到“所有可能的路径”。（思路。）</li></ol><h2 id="第-27-章" tabindex="-1">第 27 章 <a class="header-anchor" href="#第-27-章" aria-label="Permalink to &quot;第 27 章&quot;">​</a></h2><ol><li>∞（OpenFGA 的带权图：<code>doc#viewer user=inf</code>、<code>team#member user=inf</code>，已验证）。weight2 不能用：它要求 userset 节点对用户类型的权重恰好为 1，<code>team#member</code> 是 ∞（团队可以嵌套，“用户直接所在的团队”不等于“用户所在的所有团队”）。</li><li>思路见题目；注意每层的去重（已访问的组）、深度上限，以及和对象一侧组集合的提前相交。（未实现。）</li><li>要点：权重 ∞ 说明确实递归；递归关系必须是它自己，说明只有一种递归方式；不能是元组环的一部分，因为跨关系的环里集合运算的“自身展开”不再成立；只有一条边指向 OR 节点，保证结构是并集；TTU 边计算的关系相同，保证是“同一个关系沿父链递归”；其他边权重为 1，保证非递归部分一跳就能判定。</li></ol><h2 id="第-28-章" tabindex="-1">第 28 章 <a class="header-anchor" href="#第-28-章" aria-label="Permalink to &quot;第 28 章&quot;">​</a></h2><ol><li>已验证（mini 的规划器，5 次运行，每 50 轮统计 weight2 被选次数）：场景 B 中 default 的先验改成 10ms 后，<strong>weight2 一次都没有被选中</strong>（<code>0 0 0 0 0 0 0 0</code>）；顺带测了场景 A（weight2 真的更快），仍然很快收敛到 weight2（<code>47 50 50 50</code> 之类，只是前 50 轮多选了几次 default）。先验低到和实际接近时，探索代价几乎为零。</li><li>思路：λ 封顶相当于只记住最近约 50 个观察，场景 C 的转向预计在约 50 轮内完成；场景 A 不受影响，因为一直观察到的就是同一个值。（未实测。）</li><li>每个策略各抽一个样本，选最小值，与遍历顺序无关；只有当两个抽样值<strong>完全相等</strong>时，先遍历到的那个获胜，此时选择取决于随机的遍历顺序。连续分布下这几乎不会发生。</li></ol><h2 id="第-29-章" tabindex="-1">第 29 章 <a class="header-anchor" href="#第-29-章" aria-label="Permalink to &quot;第 29 章&quot;">​</a></h2><ol><li><code>ConstantTimeCompare</code> 返回 0 或 1，<code>|=</code> 之后只要有一个匹配就是 1，否则是 0，结果只能是 0 或 1。两个相同的密钥都匹配时，<code>1|1</code> 仍是 1，不影响结果。</li><li>思路：中间件从 <code>r.PathValue(&quot;store_id&quot;)</code> 或路径前缀取 store ID；<code>ListStores</code> 只返回该密钥对应的 store（需要服务层配合过滤）；<code>CreateStore</code> 需要一个单独的管理密钥。这实际上是在用配置文件实现第 29 章的访问控制。（未实现。）</li><li>两个模块超过了 <code>MaxModulesInRequest = 1</code>，<code>Authorize</code> 返回内部错误 <code>the principal cannot write tuples of more than 1 module(s) in a single request (modules in request: 2)</code>（<code>authz.go:230</code>）；但服务层把所有授权失败都转成统一的 <code>ErrUnauthorizedResponse</code>（<code>server.go:1140</code>、<code>:1218</code>），调用方看到的是 <code>the principal is not authorized to perform the action</code>（forbidden）。</li></ol><h2 id="第-30-章" tabindex="-1">第 30 章 <a class="header-anchor" href="#第-30-章" aria-label="Permalink to &quot;第 30 章&quot;">​</a></h2><ol><li>每个不同的标签值组合都是一条时间序列。1 万个 store × 约 10 个 API × 若干状态码 × 直方图的十几个桶，就是上百万条序列，Prometheus 会被拖垮；而且路径里的 store ID 对聚合毫无意义。</li><li>思路：在 <code>CachedCheckResolver</code> 上已有 <code>Hits</code>/<code>Misses</code> 计数，再加一个“命中但已失效”的计数，注册成 <code>CounterFunc</code>；在 <code>TestCacheInvalidation</code> 中断言：第一次 Check 后 misses=1，陈旧读 hits=1，控制器刷新后 invalid hits=1。（未实现；v1.0 的 Docker 端到端脚本已经导出了 <code>minifga_check_cache_hits_total</code> 和 <code>misses_total</code>。）</li><li>配置项 <code>RequestDurationDatastoreQueryCountBuckets</code> 和 <code>RequestDurationDispatchCountBuckets</code>，默认都是 <code>[&quot;50&quot;, &quot;200&quot;]</code>（<code>config.go:879–880</code>；<code>server.go:917</code> 的默认值 <code>[]uint{50, 200}</code>），所以标签值只有 <code>50</code>、<code>200</code>、<code>+Inf</code> 三种。</li></ol><h2 id="第-31-章" tabindex="-1">第 31 章 <a class="header-anchor" href="#第-31-章" aria-label="Permalink to &quot;第 31 章&quot;">​</a></h2><ol><li>递归的语义是最小不动点。从进入递归的节点出发做深度优先遍历，把“回到路径上已有的节点”当作 false：任何真正的成员都能通过一条<strong>不回头</strong>的路径到达，这条路径会被其他分支找到，所以入口节点的结果是精确的，exclusion 拿到的正是这个结果。但递归内部的节点（a、b、c 例子中的 b）在求值时“回到 a”被截断，它自己的 false 只是低估；单独问 b 时答案是 true。缓存按子问题存储，存下 b 的 false 就会在之后的单独查询中返回错误答案。</li><li>预测：<code>viewer: [user] or viewer from parent</code> 满足 <code>TTUUseRecursiveResolver</code> 的条件，文件夹成环、subtract 一侧经过这种环时，会出现第三类差异（OpenFGA 的 ListUsers 返回空，而它的 Check 为 true）。（未实测。）</li><li>例：主实现走 weight2，一条带条件的元组缺参数被“once-valid”规则忽略，返回 false；影子实现（例如另一种策略）读到那条元组并报缺参数错误（第 14 章：缺参数报错与否取决于策略）。这种差异不是“结果不同”而是“影子出错”，只记 warn 日志，避免把已知的策略差异当成告警，同时不影响主路径。</li></ol>',68)])])}const g=o(r,[["render",a]]);export{m as __pageData,g as default};
